alter table public.nutrition_targets add column if not exists hydration_ml integer, add column if not exists target_range jsonb, add column if not exists methodology_version text, add column if not exists profile_snapshot_id uuid references public.personalization_profile_snapshots(id) on delete restrict;
create index if not exists nutrition_targets_profile_snapshot_idx on public.nutrition_targets(profile_snapshot_id);
create table public.activity_targets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,profile_snapshot_id uuid not null references public.personalization_profile_snapshots(id) on delete restrict,steps_low integer not null check(steps_low>=0),steps_high integer not null check(steps_high>=steps_low),cardio_sessions smallint not null check(cardio_sessions between 0 and 7),cardio_minutes smallint not null check(cardio_minutes between 0 and 300),intensity text not null,reason_codes text[] not null,engine_version text not null,ruleset_version text not null,effective_from timestamptz not null default now(),effective_to timestamptz,created_at timestamptz not null default now());
create index activity_targets_owner_effective_idx on public.activity_targets(user_id,effective_from desc);create index activity_targets_profile_idx on public.activity_targets(profile_snapshot_id);
create table public.nutrition_preferences(user_id uuid primary key references auth.users(id) on delete cascade,diet_style text,allergies text[] not null default '{}',dislikes text[] not null default '{}',tracking_style text not null default 'flexible' check(tracking_style in('numbers','flexible','habits')),meals_per_day smallint not null default 3 check(meals_per_day between 1 and 8),updated_at timestamptz not null default now());
create table public.supplement_profiles(slug text primary key,name text not null,purpose text not null,evidence_grade text not null check(evidence_grade in('strong','moderate','limited')),guidance text not null,safety_note text not null,review_status text not null default 'reviewed',content_version text not null);
create table public.user_supplements(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,supplement_slug text not null references public.supplement_profiles(slug) on delete restrict,state text not null default 'considering' check(state in('considering','using','declined')),created_at timestamptz not null default now(),unique(user_id,supplement_slug));create index user_supplements_owner_idx on public.user_supplements(user_id);
insert into public.supplement_profiles values('creatine-monohydrate','Creatine monohydrate','Strength and high-intensity performance','strong','A common evidence-based approach is 3–5 g daily. Loading is optional.','Check with a qualified clinician when pregnant, under 18, managing kidney disease, or taking interacting medication.','reviewed','1.0.0'),('protein-powder','Protein powder','Convenient dietary protein','moderate','Use only when helpful for meeting the protein range with foods you tolerate.','Review ingredients for allergens; this is food support, not a required supplement.','reviewed','1.0.0'),('caffeine','Caffeine','Short-term alertness and performance','strong','If appropriate, use the lowest effective amount and protect sleep.','Avoid or seek clinical advice with pregnancy, heart rhythm concerns, anxiety sensitivity, or interacting medication.','reviewed','1.0.0'),('electrolytes','Electrolytes','Replace sweat losses during long or hot sessions','moderate','Most routine sessions need water; electrolytes may help with prolonged heat and heavy sweating.','People managing blood pressure, kidney, or fluid conditions should seek individual guidance.','reviewed','1.0.0') on conflict(slug) do update set guidance=excluded.guidance,safety_note=excluded.safety_note,content_version=excluded.content_version;
alter table public.activity_targets enable row level security;alter table public.nutrition_preferences enable row level security;alter table public.supplement_profiles enable row level security;alter table public.user_supplements enable row level security;
create policy "activity owner select" on public.activity_targets for select to authenticated using((select auth.uid())=user_id);create policy "activity owner insert" on public.activity_targets for insert to authenticated with check((select auth.uid())=user_id);create policy "preferences owner all" on public.nutrition_preferences for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy "supplement catalog read" on public.supplement_profiles for select to authenticated using(true);create policy "user supplements owner all" on public.user_supplements for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
grant select,insert on public.activity_targets to authenticated;grant select,insert,update on public.nutrition_preferences to authenticated;grant select on public.supplement_profiles to authenticated;grant select,insert,update,delete on public.user_supplements to authenticated;
